#include <zephyr/ztest.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <zephyr/kernel.h>

#define NUM_THREADS 4
#define DATA_SIZE 16

static pthread_key_t test_key;
static K_SEM_DEFINE(destructor_sem, 0, NUM_THREADS);

static void key_destructor(void *data)
{
    if (data != NULL) {
        free(data);
        k_sem_give(&destructor_sem);
    }
}

static void *thread_entry(void *arg)
{
    char *data = malloc(DATA_SIZE);

    zassert_not_null(data, "Failed to allocate thread-specific data");
    snprintk(data, DATA_SIZE, "Thread %d", (int)(intptr_t)arg);

    int rc = pthread_setspecific(test_key, data);

    zassert_equal(rc, 0, "pthread_setspecific failed");

    /* Thread exits, destructor should be called */
    return NULL;
}

ZTEST(key, test_correct_key_is_deleted)
{
    pthread_key_t key_a, key_b;
    int rc;

    rc = pthread_key_create(&key_a, NULL);
    zassert_equal(rc, 0, "pthread_key_create failed");

    rc = pthread_key_create(&key_b, NULL);
    zassert_equal(rc, 0, "pthread_key_create failed");

    rc = pthread_key_delete(key_a);
    zassert_equal(rc, 0, "pthread_key_delete failed");

    rc = pthread_key_delete(key_b);
    zassert_equal(rc, 0, "pthread_key_delete failed");
}

ZTEST(key, test_key_1toN_thread)
{
    pthread_t threads[NUM_THREADS];
    int rc;

    /* 1. Create the key with a destructor */
    rc = pthread_key_create(&test_key, key_destructor);
    zassert_equal(rc, 0, "pthread_key_create failed");

    /* 2. Create N threads, each setting data for the key */
    for (int i = 0; i < NUM_THREADS; i++) {
        rc = pthread_create(&threads[i], NULL, thread_entry, (void *)(intptr_t)i);
        zassert_equal(rc, 0, "pthread_create failed");
    }

    /* 3. Join all threads */
    for (int i = 0; i < NUM_THREADS; i++) {
        rc = pthread_join(threads[i], NULL);
        zassert_equal(rc, 0, "pthread_join failed");
    }

    /* 4. Wait for all destructors to be called */
    for (int i = 0; i < NUM_THREADS; i++) {
        k_sem_take(&destructor_sem, K_FOREVER);
    }

    /* 5. Delete the key */
    rc = pthread_key_delete(test_key);
    zassert_equal(rc, 0, "pthread_key_delete failed");

    /* Reset semaphore for next test run if any */
    while (k_sem_count_get(&destructor_sem) > 0) {
        k_sem_take(&destructor_sem, K_NO_WAIT);
    }
}

ZTEST_SUITE(key, NULL, NULL, NULL, NULL, NULL);
